namespace Orders;

public sealed class OrderService
{
    private readonly List<Order> _orders = new();

    public void AddOrder(Order order) => _orders.Add(order);

    public decimal TotalAmount() => _orders.Sum(o => o.Amount);
}

using Orders;

var service = new OrderService();
service.AddOrder(new Order(1, "acme", 12.5m));
Console.WriteLine(service.TotalAmount());

